/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import { readFileSync } from 'fs'

// Get mode from command line
const args = process.argv.slice(2)
if (args.length !== 1 || !['json', 'keys'].includes(args[0])) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
const mode = args[0]

// Read stdin
let input = ''
try {
  input = readFileSync(0, 'utf-8')
} catch {
  input = ''
}

// Remove trailing newline if present
if (input.endsWith('\n')) {
  input = input.slice(0, -1)
}

// Parse TOML
try {
  const doc = parseToml(input)
  if (mode === 'json') {
    console.log(formatJson(doc))
  } else {
    console.log(formatKeys(doc))
  }
  process.exit(0)
} catch (err) {
  process.stderr.write(err.message + '\n')
  process.exit(2)
}

function parseToml(input) {
  const lines = input.split('\n')
  const doc = {}
  let currentTable = doc
  const tableStack = [{ table: doc, path: [] }]

  for (let lineNum = 1; lineNum <= lines.length; lineNum++) {
    let line = lines[lineNum - 1]

    // Remove comments
    let commentPos = findCommentStart(line)
    if (commentPos !== -1) {
      line = line.substring(0, commentPos)
    }
    line = line.trimEnd()

    // Check if this is a comment or blank line
    const trimmed = line.trimStart()
    if (!trimmed || trimmed[0] === '#' || trimmed[0] === ';') {
      continue
    }

    // Check for table header
    if (trimmed[0] === '[') {
      const result = parseTableHeader(trimmed, lineNum)
      if (result.isArrayOfTables) {
        // [[name]]
        const { path } = result
        currentTable = createArrayOfTablesHeader(doc, path, lineNum)
      } else {
        // [name]
        const { path } = result
        currentTable = createTableHeader(doc, path, lineNum)
      }
      tableStack[tableStack.length - 1] = { table: currentTable, path: result.path }
    } else {
      // Key-value pair
      const { key, value } = parseKeyValue(trimmed, lineNum)
      assignValue(currentTable, key, value, lineNum)
    }
  }

  return doc
}

function findCommentStart(line) {
  let inString = false
  let stringChar = null
  let escaped = false

  for (let i = 0; i < line.length; i++) {
    if (escaped) {
      escaped = false
      continue
    }

    const char = line[i]

    if (inString) {
      if (char === '\\') {
        escaped = true
      } else if (char === stringChar) {
        inString = false
      }
    } else {
      if (char === '"' || char === "'") {
        inString = true
        stringChar = char
      } else if (char === '#' || char === ';') {
        return i
      }
    }
  }

  return -1
}

function parseTableHeader(line, lineNum) {
  // Remove leading whitespace
  const match = line.match(/^(\[\[?)(.+?)(\]\]?)\s*$/)
  if (!match) {
    throw new ParseError(lineNum, 'unterminated table header')
  }

  const openBrackets = match[1]
  const content = match[2]
  const closeBrackets = match[3]

  if (openBrackets.length !== closeBrackets.length) {
    throw new ParseError(lineNum, 'unterminated table header')
  }

  const isArrayOfTables = openBrackets.length === 2

  // Parse the dotted name
  const path = parseDottedName(content, lineNum)

  // Check for trailing text
  const afterClose = line.substring(line.lastIndexOf(closeBrackets) + closeBrackets.length).trim()
  if (afterClose) {
    throw new ParseError(lineNum, 'trailing text after a table header')
  }

  return { path, isArrayOfTables }
}

function parseDottedName(str, lineNum) {
  const parts = []
  let current = ''
  let i = 0

  while (i < str.length) {
    const char = str[i]

    if (char === ' ' || char === '\t') {
      i++
      continue
    }

    if (char === '.') {
      if (!current) {
        throw new ParseError(lineNum, 'expected a name')
      }
      parts.push(current)
      current = ''
      i++
    } else if (char === '"') {
      // Quoted name
      i++
      let name = ''
      while (i < str.length) {
        if (str[i] === '\\') {
          i++
          if (i >= str.length) {
            throw new ParseError(lineNum, 'unterminated string')
          }
          name += parseEscape(str[i], lineNum)
          i++
        } else if (str[i] === '"') {
          i++
          break
        } else {
          name += str[i]
          i++
        }
      }
      current = name
    } else if (char === "'") {
      // Literal string
      i++
      let name = ''
      while (i < str.length && str[i] !== "'") {
        name += str[i]
        i++
      }
      if (i >= str.length) {
        throw new ParseError(lineNum, 'unterminated string')
      }
      i++
      current = name
    } else if (/[a-zA-Z0-9_-]/.test(char)) {
      current += char
      i++
    } else {
      throw new ParseError(lineNum, 'expected a name')
    }
  }

  if (current) {
    parts.push(current)
  }

  if (parts.length === 0) {
    throw new ParseError(lineNum, 'expected a name')
  }

  return parts
}

function parseKeyValue(line, lineNum) {
  const eqPos = line.indexOf('=')
  if (eqPos === -1) {
    throw new ParseError(lineNum, 'expected key = value')
  }

  const keyPart = line.substring(0, eqPos).trimEnd()
  const valuePart = line.substring(eqPos + 1).trimStart()

  if (!keyPart) {
    throw new ParseError(lineNum, 'expected a name')
  }

  const key = parseDottedName(keyPart, lineNum)
  const value = parseValue(valuePart, lineNum)

  return { key, value }
}

function parseValue(str, lineNum) {
  let i = 0

  // Skip whitespace
  while (i < str.length && (str[i] === ' ' || str[i] === '\t')) {
    i++
  }

  if (i >= str.length) {
    throw new ParseError(lineNum, 'expected a value')
  }

  const char = str[i]
  let value
  let consumed

  if (char === '"') {
    // Basic string
    const result = parseBasicString(str.substring(i), lineNum)
    value = { type: 'string', value: result.value }
    consumed = result.consumed
  } else if (char === "'") {
    // Literal string
    const result = parseLiteralString(str.substring(i), lineNum)
    value = { type: 'string', value: result.value }
    consumed = result.consumed
  } else if (char === '[') {
    // Array
    const result = parseArray(str.substring(i), lineNum)
    value = result.value
    consumed = result.consumed
  } else if (char === '{') {
    // Inline table
    const result = parseInlineTable(str.substring(i), lineNum)
    value = result.value
    consumed = result.consumed
  } else if (str.substring(i).startsWith('true')) {
    value = { type: 'boolean', value: true }
    consumed = 4
  } else if (str.substring(i).startsWith('false')) {
    value = { type: 'boolean', value: false }
    consumed = 5
  } else {
    // Try to parse as number or bare word
    const result = parseNumber(str.substring(i), lineNum)
    value = result.value
    consumed = result.consumed
  }

  // Check for trailing text
  const after = str.substring(i + consumed).trimStart()
  if (after && !after.startsWith('#') && !after.startsWith(';')) {
    throw new ParseError(lineNum, 'trailing text after a value')
  }

  return value
}

function parseBasicString(str, lineNum) {
  if (str[0] !== '"') {
    throw new ParseError(lineNum, 'unterminated string')
  }

  let result = ''
  let i = 1

  while (i < str.length) {
    if (str[i] === '\\') {
      i++
      if (i >= str.length) {
        throw new ParseError(lineNum, 'unterminated string')
      }
      result += parseEscape(str[i], lineNum)
      i++
    } else if (str[i] === '"') {
      return { value: result, consumed: i + 1 }
    } else if (str[i] === '\n') {
      throw new ParseError(lineNum, 'unterminated string')
    } else {
      result += str[i]
      i++
    }
  }

  throw new ParseError(lineNum, 'unterminated string')
}

function parseLiteralString(str, lineNum) {
  if (str[0] !== "'") {
    throw new ParseError(lineNum, 'unterminated string')
  }

  let result = ''
  let i = 1

  while (i < str.length) {
    if (str[i] === "'") {
      return { value: result, consumed: i + 1 }
    } else if (str[i] === '\n') {
      throw new ParseError(lineNum, 'unterminated string')
    } else {
      result += str[i]
      i++
    }
  }

  throw new ParseError(lineNum, 'unterminated string')
}

function parseEscape(char, lineNum) {
  switch (char) {
    case 'n':
      return '\n'
    case 't':
      return '\t'
    case 'r':
      return '\r'
    case '\\':
      return '\\'
    case '"':
      return '"'
    case '0':
      return '\0'
    case 'u':
      // Will be handled in context
      return char
    default:
      throw new ParseError(lineNum, `invalid escape \\${char}`)
  }
}

function parseNumber(str, lineNum) {
  // Try to match number patterns
  let i = 0

  // Optional sign
  if (str[i] === '+' || str[i] === '-') {
    i++
  }

  if (i >= str.length) {
    throw new ParseError(lineNum, `invalid value ${str.split(/[\s#;]/)[0]}`)
  }

  // Must have at least one digit
  if (!/\d/.test(str[i])) {
    const word = str.match(/^[^\s#;,\]\}]*/)[0]
    throw new ParseError(lineNum, `invalid value ${word}`)
  }

  let hasDecimal = false
  let hasExponent = false

  // Read digits and underscores
  while (i < str.length && (/\d/.test(str[i]) || str[i] === '_')) {
    if (str[i] === '_') {
      // Check valid underscore usage
      if (i === 0 || i + 1 >= str.length || !/\d/.test(str[i - 1]) || !/\d/.test(str[i + 1])) {
        break
      }
    }
    i++
  }

  // Check for decimal point
  if (i < str.length && str[i] === '.') {
    hasDecimal = true
    i++
    if (i >= str.length || !/\d/.test(str[i])) {
      const word = str.substring(0, i).match(/^[^\s#;,\]\}]*/)[0]
      throw new ParseError(lineNum, `invalid value ${word}`)
    }
    while (i < str.length && (/\d/.test(str[i]) || str[i] === '_')) {
      i++
    }
  }

  // Check for exponent
  if (i < str.length && (str[i] === 'e' || str[i] === 'E')) {
    hasExponent = true
    i++
    if (i < str.length && (str[i] === '+' || str[i] === '-')) {
      i++
    }
    if (i >= str.length || !/\d/.test(str[i])) {
      const word = str.substring(0, i).match(/^[^\s#;,\]\}]*/)[0]
      throw new ParseError(lineNum, `invalid value ${word}`)
    }
    while (i < str.length && (/\d/.test(str[i]) || str[i] === '_')) {
      i++
    }
  }

  const numStr = str.substring(0, i).replace(/_/g, '')
  const num = Number(numStr)

  if (hasDecimal || hasExponent) {
    return { 
      value: { type: 'float', value: num },
      consumed: i
    }
  } else {
    return {
      value: { type: 'integer', value: num },
      consumed: i
    }
  }
}

function parseArray(str, lineNum) {
  if (str[0] !== '[') {
    throw new ParseError(lineNum, 'unterminated array')
  }

  const items = []
  let i = 1

  while (i < str.length) {
    // Skip whitespace and newlines
    while (i < str.length && /[\s]/.test(str[i])) {
      i++
    }

    if (i >= str.length) {
      throw new ParseError(lineNum, 'unterminated array')
    }

    if (str[i] === ']') {
      return { value: { type: 'array', value: items }, consumed: i + 1 }
    }

    // Skip comments
    if (str[i] === '#' || str[i] === ';') {
      while (i < str.length && str[i] !== '\n') {
        i++
      }
      if (i < str.length) {
        i++ // skip newline
      }
      continue
    }

    // Parse value
    const valueStr = str.substring(i)
    const result = parseValue(valueStr, lineNum)
    items.push(result)
    i += result.consumed || 0

    // Skip whitespace and comments
    while (i < str.length && /[\s]/.test(str[i])) {
      i++
    }

    if (i >= str.length) {
      throw new ParseError(lineNum, 'unterminated array')
    }

    if (str[i] === ',') {
      i++
      while (i < str.length && /[\s]/.test(str[i])) {
        i++
      }
      if (i < str.length && (str[i] === '#' || str[i] === ';')) {
        while (i < str.length && str[i] !== '\n') {
          i++
        }
        if (i < str.length) {
          i++
        }
        while (i < str.length && /[\s]/.test(str[i])) {
          i++
        }
      }
      // Allow trailing comma and closing bracket
      if (i < str.length && str[i] === ']') {
        i++
        return { value: { type: 'array', value: items }, consumed: i }
      }
    } else if (str[i] === ']') {
      i++
      return { value: { type: 'array', value: items }, consumed: i }
    } else {
      throw new ParseError(lineNum, 'unterminated array')
    }
  }

  throw new ParseError(lineNum, 'unterminated array')
}

function parseInlineTable(str, lineNum) {
  if (str[0] !== '{') {
    throw new ParseError(lineNum, 'unterminated inline table')
  }

  const table = {}
  let i = 1

  while (i < str.length) {
    // Skip whitespace
    while (i < str.length && (str[i] === ' ' || str[i] === '\t')) {
      i++
    }

    if (i >= str.length) {
      throw new ParseError(lineNum, 'unterminated inline table')
    }

    if (str[i] === '}') {
      return { value: { type: 'table', value: table }, consumed: i + 1 }
    }

    // Parse key = value
    const remaining = str.substring(i)
    const eqPos = findUnquotedEquals(remaining, lineNum)
    if (eqPos === -1) {
      throw new ParseError(lineNum, 'expected = in an inline table')
    }

    const keyPart = remaining.substring(0, eqPos).trimEnd()
    const afterEq = remaining.substring(eqPos + 1).trimStart()

    const key = parseDottedName(keyPart, lineNum)
    const valueResult = parseValue(afterEq, lineNum)

    let finalTable = table
    for (let j = 0; j < key.length - 1; j++) {
      if (!finalTable[key[j]]) {
        finalTable[key[j]] = { type: 'table', value: {} }
      }
      finalTable = finalTable[key[j]].value
    }

    const lastKey = key[key.length - 1]
    if (finalTable.hasOwnProperty(lastKey)) {
      throw new ParseError(lineNum, `key ${key.join('.')} is defined twice`)
    }
    finalTable[lastKey] = valueResult

    i += eqPos + 1 + afterEq.length - afterEq.trimStart().length + (valueResult.consumed || 1)

    // Skip whitespace
    while (i < str.length && (str[i] === ' ' || str[i] === '\t')) {
      i++
    }

    if (i >= str.length) {
      throw new ParseError(lineNum, 'unterminated inline table')
    }

    if (str[i] === ',') {
      i++
    } else if (str[i] === '}') {
      i++
      return { value: { type: 'table', value: table }, consumed: i }
    } else {
      throw new ParseError(lineNum, 'unterminated inline table')
    }
  }

  throw new ParseError(lineNum, 'unterminated inline table')
}

function findUnquotedEquals(str, lineNum) {
  let inString = false
  let stringChar = null

  for (let i = 0; i < str.length; i++) {
    const char = str[i]

    if (inString) {
      if (char === stringChar) {
        inString = false
      }
    } else {
      if (char === '"' || char === "'") {
        inString = true
        stringChar = char
      } else if (char === '=') {
        return i
      }
    }
  }

  return -1
}

function createTableHeader(doc, path, lineNum) {
  let current = doc

  for (let i = 0; i < path.length; i++) {
    const key = path[i]

    if (!current.hasOwnProperty(key)) {
      current[key] = { type: 'table', value: {}, _defined: false, _implicit: i < path.length - 1 }
    } else {
      const existing = current[key]
      if (existing.type !== 'table') {
        throw new ParseError(lineNum, `${path.slice(0, i + 1).join('.')} is not a table`)
      }
      if (i === path.length - 1) {
        if (!existing._implicit) {
          throw new ParseError(lineNum, `table ${path.join('.')} is defined twice`)
        }
      }
    }

    if (i === path.length - 1) {
      current[key]._defined = true
      current[key]._implicit = false
    } else {
      current[key]._implicit = true
    }

    current = current[key].value
  }

  return current
}

function createArrayOfTablesHeader(doc, path, lineNum) {
  let current = doc

  for (let i = 0; i < path.length - 1; i++) {
    const key = path[i]

    if (!current.hasOwnProperty(key)) {
      current[key] = { type: 'table', value: {} }
    } else {
      const existing = current[key]
      if (existing.type !== 'table') {
        throw new ParseError(lineNum, `${path.slice(0, i + 1).join('.')} is not a table`)
      }
    }

    current = current[key].value
  }

  const lastKey = path[path.length - 1]

  if (!current.hasOwnProperty(lastKey)) {
    current[lastKey] = { type: 'array', value: [] }
  } else {
    const existing = current[lastKey]
    if (existing.type !== 'array') {
      throw new ParseError(lineNum, `${path.join('.')} is not an array of tables`)
    }
  }

  const newTable = { type: 'table', value: {} }
  current[lastKey].value.push(newTable)

  return newTable.value
}

function assignValue(table, key, value, lineNum) {
  let current = table

  for (let i = 0; i < key.length - 1; i++) {
    const k = key[i]

    if (!current.hasOwnProperty(k)) {
      current[k] = { type: 'table', value: {} }
    } else {
      const existing = current[k]
      if (existing.type !== 'table' && existing.type !== 'array') {
        throw new ParseError(lineNum, `${key.slice(0, i + 1).join('.')} is not a table`)
      }
      if (existing.type === 'array') {
        current = existing.value[existing.value.length - 1]
        continue
      }
    }

    current = current[k].value
  }

  const lastKey = key[key.length - 1]

  if (current.hasOwnProperty(lastKey)) {
    throw new ParseError(lineNum, `key ${key.join('.')} is defined twice`)
  }

  current[lastKey] = value
}

function formatJson(obj, indent = 0) {
  const spaces = ' '.repeat(indent)
  const nextSpaces = ' '.repeat(indent + 2)

  if (obj.type === 'table') {
    const keys = Object.keys(obj.value).filter(k => !k.startsWith('_')).sort()
    if (keys.length === 0) {
      return '{}'
    }
    const lines = ['{']
    for (let i = 0; i < keys.length; i++) {
      const k = keys[i]
      const v = obj.value[k]
      const formatted = formatJsonValue(v, indent + 2)
      lines.push(`${nextSpaces}"${k}": ${formatted}${i < keys.length - 1 ? ',' : ''}`)
    }
    lines.push(`${spaces}}`)
    return lines.join('\n')
  } else if (obj.type === 'array') {
    if (obj.value.length === 0) {
      return '[]'
    }
    const lines = ['[']
    for (let i = 0; i < obj.value.length; i++) {
      const item = obj.value[i]
      if (item.type === 'table') {
        const formatted = formatJson(item, indent + 2)
        lines.push(`${nextSpaces}${formatted}${i < obj.value.length - 1 ? ',' : ''}`)
      } else {
        const formatted = formatJsonValue(item, indent + 2)
        lines.push(`${nextSpaces}${formatted}${i < obj.value.length - 1 ? ',' : ''}`)
      }
    }
    lines.push(`${spaces}]`)
    return lines.join('\n')
  } else {
    return formatJsonValue(obj, indent)
  }
}

function formatJsonValue(v, indent = 0) {
  if (v.type === 'string') {
    return JSON.stringify(v.value)
  } else if (v.type === 'boolean') {
    return v.value ? 'true' : 'false'
  } else if (v.type === 'integer') {
    return String(v.value)
  } else if (v.type === 'float') {
    return String(v.value)
  } else if (v.type === 'array') {
    return formatJson(v, indent)
  } else if (v.type === 'table') {
    return formatJson(v, indent)
  }
}

function formatKeys(obj, path = []) {
  const output = []
  const keys = Object.keys(obj).filter(k => !k.startsWith('_')).sort()

  for (const k of keys) {
    const v = obj[k]
    const newPath = [...path, k]
    const pathStr = newPath.join('.')

    if (v.type === 'table') {
      output.push(`${pathStr} table`)
      output.push(...formatKeys(v.value, newPath))
    } else if (v.type === 'array') {
      output.push(`${pathStr} array`)
      for (let i = 0; i < v.value.length; i++) {
        const item = v.value[i]
        if (item.type === 'table') {
          output.push(...formatKeys(item.value, [...newPath, `[${i}]`]))
        }
      }
    } else {
      output.push(`${pathStr} ${v.type}`)
    }
  }

  return output
}

class ParseError extends Error {
  constructor(lineNum, reason) {
    super(`error: line ${lineNum}: ${reason}`)
  }
}
"}

