 * Paths. A path is an array whose elements are either strings (object keys as
 * written after decoding) or numbers (array indices).
 */

export function joinPath(parts) {
  let out = ''
  for (const part of parts) {
    if (typeof part === 'number') out += `[${part}]`
    else out += out === '' ? part : `.${part}`
  }
  return out
}

/** Compare two strings by code point, ascending. */
export function compareByCodePoint(a, b) {
  const left = Array.from(a)
  const right = Array.from(b)
  const n = Math.min(left.length, right.length)
  for (let i = 0; i < n; i++) {
    const x = left[i].codePointAt(0)
    const y = right[i].codePointAt(0)
    if (x !== y) return x < y ? -1 : 1
  }
  if (left.length === right.length) return 0
  return left.length < right.length ? -1 : 1
}

export function sortedKeys(object) {
  return Object.keys(object).sort(compareByCodePoint)
}
