{"file_path":"src/format.js","content":"/**
 * The two output modes: canonical JSON and the flat list of paths and types.
 */

import { joinPath, sortedKeys } from './path.js'

export function toJson(node, indent = 0) {
  const pad = ' '.repeat(indent)
  const inner = ' '.repeat(indent + 2)

  if (node.t === 'table') {
    const keys = sortedKeys(node.v)
    if (keys.length === 0) return '{}'
    const parts = keys.map(
      (key) => `${inner}${JSON.stringify(key)}: ${toJson(node.v[key], indent + 2)}`
    )
    return `{\n${parts.join(',\n')}\n${pad}}`
  }

  if (node.t === 'array') {
    if (node.v.length === 0) return '[]'
    const parts = node.v.map((item) => `${inner}${toJson(item, indent + 2)}`)
    return `[\n${parts.join(',\n')}\n${pad}]`
  }

  if (node.t === 'string') return JSON.stringify(node.v)
  if (node.t === 'boolean') return node.v ? 'true' : 'false'
  return numberText(node.v)
}

function numberText(value) {
  return JSON.stringify(value)
}

export function toKeys(root) {
  const out = []
  walk(root, [], out)
  return out
}

function walk(node, path, out) {
  if (node.t === 'table') {
    for (const key of sortedKeys(node.v)) {
      const child = node.v[key]
      const childPath = path.concat([key])
      out.push(`${joinPath(childPath)} ${child.t}`)
      walk(child, childPath, out)
    }
    return
  }
  if (node.t === 'array') {
    for (let i = 0; i < node.v.length; i++) {
      const child = node.v[i]
      const childPath = path.concat([i])
      out.push(`${joinPath(childPath)} ${child.t}`)
      walk(child, childPath, out)
    }
  }
}
