{"file_path":"src/parser.js","content":"/**
 * The configuration document parser. Every directive fits on one line, so the
 * scanner never looks past the line it was given.
 */

import { joinPath } from './path.js'

export class ParseError extends Error {
  constructor(line, reason) {
    super(`error: line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

const NAME_CHAR = /[A-Za-z0-9_-]/
const INTEGER = /^[+-]?[0-9]+(?:_[0-9]+)*$/
const DIGITS = '[0-9]+(?:_[0-9]+)*'
const FLOAT = new RegExp(
  `^[+-]?${DIGITS}(?:\\.${DIGITS})?(?:[eE][+-]?${DIGITS})?$`
)

class Scanner {
  constructor(text, line) {
    this.s = text
    this.i = 0
    this.line = line
  }

  fail(reason) {
    throw new ParseError(this.line, reason)
  }

  eof() {
    return this.i >= this.s.length
  }

  peek() {
    return this.s[this.i]
  }

  /** A `#` or `;` here would start a comment that runs to the end of the line. */
  atComment() {
    const c = this.s[this.i]
    return c === '#' || c === ';'
  }

  ws() {
    while (!this.eof() && (this.s[this.i] === ' ' || this.s[this.i] === '\t')) this.i++
  }

  /** Skip spaces and tabs; true when only a comment, or nothing, is left. */
  ended() {
    this.ws()
    return this.eof() || this.atComment()
  }
}

function newTable(explicit) {
  return { t: 'table', v: Object.create(null), explicit }
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = newTable(true)
  let current = root
  let currentPath = []

  for (let n = 0; n < lines.length; n++) {
    const sc = new Scanner(lines[n], n + 1)
    sc.ws()
    if (sc.eof() || sc.atComment()) continue

    if (sc.peek() === '[') {
      const header = parseHeader(sc)
      const applied = header.array
        ? openArrayOfTables(root, header.name, sc)
        : openTable(root, header.name, sc)
      current = applied.table
      currentPath = applied.path
    } else {
      const name = parseDottedName(sc)
      sc.ws()
      if (sc.eof() || sc.atComment() || sc.peek() !== '=') sc.fail('expected key = value')
      sc.i++
      const value = parseValue(sc, currentPath.concat(name))
      if (!sc.ended()) sc.fail('trailing text after a value')
      define(current, name, value, currentPath, sc)
    }
  }

  return root
}

function parseHeader(sc) {
  sc.i++
  let array = false
  if (!sc.eof() && sc.peek() === '[') {
    array = true
    sc.i++
  }
  sc.ws()
  const name = parseDottedName(sc)
  sc.ws()
  if (sc.eof() || sc.peek() !== ']') sc.fail('unterminated table header')
  sc.i++
  if (array) {
    if (sc.eof() || sc.peek() !== ']') sc.fail('unterminated table header')
    sc.i++
  }
  if (!sc.ended()) sc.fail('trailing text after a table header')
  return { name, array }
}

/** Walk one step of a dotted path, creating the table when it is absent. */
function step(node, key, path, sc) {
  const child = node.v[key]
  if (child === undefined) {
    const made = newTable(false)
    node.v[key] = made
    return { node: made, path }
  }
  if (child.t === 'table') return { node: child, path }
  if (child.t === 'array') {
    const last = child.v[child.v.length - 1]
    if (last !== undefined && last.t === 'table') {
      return { node: last, path: path.concat([child.v.length - 1]) }
    }
  }
  sc.fail(`${joinPath(path)} is not a table`)
}

function walkPrefix(root, name, sc) {
  let node = root
  let path = []
  for (let i = 0; i < name.length - 1; i++) {
    path = path.concat([name[i]])
    const next = step(node, name[i], path, sc)
    node = next.node
    path = next.path
  }
  return { node, path }
}

function openTable(root, name, sc) {
  const { node, path } = walkPrefix(root, name, sc)
  const key = name[name.length - 1]
  const full = path.concat([key])
  const existing = node.v[key]
  if (existing === undefined) {
    const made = newTable(true)
    node.v[key] = made
    return { table: made, path: full }
  }
  if (existing.t !== 'table') sc.fail(`${joinPath(full)} is not a table`)
  if (existing.explicit) sc.fail(`table ${joinPath(full)} is defined twice`)
  existing.explicit = true
  return { table: existing, path: full }
}

function openArrayOfTables(root, name, sc) {
  const { node, path } = walkPrefix(root, name, sc)
  const key = name[name.length - 1]
  const full = path.concat([key])
  let existing = node.v[key]
  if (existing === undefined) {
    existing = { t: 'array', v: [], aot: true }
    node.v[key] = existing
  } else if (existing.t !== 'array' || !existing.aot) {
    sc.fail(`${joinPath(full)} is not an array of tables`)
  }
  const made = newTable(true)
  existing.v.push(made)
  return { table: made, path: full.concat([existing.v.length - 1]) }
}

/** Assign a value at a dotted name inside a table. */
function define(table, name, value, base, sc) {
  let node = table
  let path = base
  for (let i = 0; i < name.length - 1; i++) {
    path = path.concat([name[i]])
    const next = step(node, name[i], path, sc)
    node = next.node
    path = next.path
  }
  const key = name[name.length - 1]
  const full = path.concat([key])
  if (node.v[key] !== undefined) sc.fail(`key ${joinPath(full)} is defined twice`)
  node.v[key] = value
