  let inString = false
  let stringChar = null
  let escaped = false

  for (let i = 0; i < line.length; i++) {
    if (escaped) {
      escaped = false
      continue
    }

    const char = line[i]

    if (inString) {
      if (char === '\\') {
        escaped = true
      } else if (char === stringChar) {
        inString = false
      }
    } else {
      if (char === '"' || char === "'") {
