          name += parseEscape(str[i], lineNum)
          i++
        } else if (str[i] === '"') {
          i++
          break
        } else {
          name += str[i]
          i++
        }
      }
      current = name
    } else if (char === "'") {
      // Literal string
      i++
      let name = ''
      while (i < str.length && str[i] !== "'") {
        name += str[i]
        i++
      }
      if (i >= str.length) {
        throw new ParseError(lineNum, 'unterminated string')
      }
      i++
      current = name
    } else if (/[a-zA-Z0-9_-]/.test(char)) {
      current += char
      i++
    } else {
      throw new ParseError(lineNum, 'expected a name')
    }
  }

  if (current) {
    parts.push(current)
  }

  if (parts.length === 0) {
    throw new ParseError(lineNum, 'expected a name')
  }

  return parts
}

function parseKeyValue(line, lineNum) {
  const eqPos = line.indexOf('=')
  if (eqPos === -1) {
    throw new ParseError(lineNum, 'expected key = value')
  }

  const keyPart = line.substring(0, eqPos).trimEnd()
  const valuePart = line.substring(eqPos + 1).trimStart()

  if (!keyPart) {
    throw new ParseError(lineNum, 'expected a name')
  }

  const key = parseDottedName(keyPart, lineNum)
  const { value, consumed } = parseValueAndCheck(valuePart, lineNum)

  return { key, value }
}

function parseValueAndCheck(str, lineNum) {
  const { value, consumed } = parseValue(str, lineNum)

  // Check for trailing text
  const after = str.substring(consumed).trimStart()
  if (after && !after.startsWith('#') && !after.startsWith(';')) {
    throw new ParseError(lineNum, 'trailing text after a value')
  }

  return { value, consumed }
}

function parseValue(str, lineNum) {
  let i = 0

  // Skip whitespace
  while (i < str.length && (str[i] === ' ' || str[i] === '\t')) {
    i++
  }

  if (i >= str.length) {
    throw new ParseError(lineNum, 'expected a value')
  }

  const char = str[i]
  let value
  let consumed

  if (char === '"') {
    // Basic string
    const result = parseBasicString(str.substring(i), lineNum)
    value = { type: 'string', value: result.value }
    consumed = result.consumed
  } else if (char === "'") {
    // Literal string
    const result = parseLiteralString(str.substring(i), lineNum)
    value = { type: 'string', value: result.value }
    consumed = result.consumed
  } else if (char === '[') {
    // Array
    const result = parseArray(str.substring(i), lineNum)
    value = result.value
    consumed = result.consumed
  } else if (char === '{') {
    // Inline table
    const result = parseInlineTable(str.substring(i), lineNum)
    value = result.value
    consumed = result.consumed
  } else if (str.substring(i).startsWith('true')) {
    value = { type: 'boolean', value: true }
    consumed = 4
  } else if (str.substring(i).startsWith('false')) {
    value = { type: 'boolean', value: false }
    consumed = 5
  } else {
    // Try to parse as number
    const result = parseNumber(str.substring(i), lineNum)
    value = result.value
    consumed = result.consumed
  }

  return { value, consumed: i + consumed }
}

function parseBasicString(str, lineNum) {
  if (str[0] !== '"') {
    throw new ParseError(lineNum, 'unterminated string')
  }

  let result = ''
  let i = 1

  while (i < str.length) {
    if (str[i] === '\\') {
      i++
      if (i >= str.length) {
        throw new ParseError(lineNum, 'unterminated string')
      }
      if (str[i] === 'u') {
        // Unicode escape
        if (i + 4 >= str.length) {
          throw new ParseError(lineNum, 'unterminated string')
        }
        const hex = str.substring(i + 1, i + 5)
        if (!/^[0-9a-fA-F]{4}$/.test(hex)) {
          throw new ParseError(lineNum, `invalid escape \\u${hex}`)
        }
        result += String.fromCharCode(parseInt(hex, 16))
        i += 5
      } else {
        result += parseEscape(str[i], lineNum)
        i++
      }
    } else if (str[i] === '"') {
      return { value: result, consumed: i + 1 }
    } else if (str[i] === '\n') {
      throw new ParseError(lineNum, 'unterminated string')
    } else {
      result += str[i]
      i++
    }
  }

  throw new ParseError(lineNum, 'unterminated string')
}

function parseLiteralString(str, lineNum) {
  if (str[0] !== "'") {
    throw new ParseError(lineNum, 'unterminated string')
  }

  let result = ''
  let i = 1

  while (i < str.length) {
    if (str[i] === "'") {
      return { value: result, consumed: i + 1 }
    } else if (str[i] === '\n') {
      throw new ParseError(lineNum, 'unterminated string')
    } else {
      result += str[i]
      i++
    }
  }

  throw new ParseError(lineNum, 'unterminated string')
}

function parseEscape(char, lineNum) {
  switch (char) {
    case 'n':
      return '\n'
    case 't':
      return '\t'
    case 'r':
      return '\r'
    case '\\':
      return '\\'
    case '"':
      return '"'
    case '0':
      return '\0'
    default:
      throw new ParseError(lineNum, `invalid escape \\${char}`)
  }
}

function parseNumber(str, lineNum) {
  let i = 0

  // Optional sign
  if (str[i] === '+' || str[i] === '-') {
    i++
  }

  if (i >= str.length || !/\d/.test(str[i])) {
    const word = str.match(/^[^\s#;,\]\}]*/)[0]
    throw new ParseError(lineNum, `invalid value ${word}`)
  }

  let hasDecimal = false
  let hasExponent = false

  // Read digits and underscores
  while (i < str.length && (/\d/.test(str[i]) || str[i] === '_')) {
    i++
  }

  // Check for decimal point
  if (i < str.length && str[i] === '.') {
    hasDecimal = true
    i++
    if (i >= str.length || !/\d/.test(str[i])) {
      const word = str.substring(0, i).match(/^[^\s#;,\]\}]*/)[0]
      throw new ParseError(lineNum, `invalid value ${word}`)
    }
    while (i < str.length && (/\d/.test(str[i]) || str[i] === '_')) {
      i++
    }
  }

  // Check for exponent
  if (i < str.length && (str[i] === 'e' || str[i] === 'E')) {
    hasExponent = true
    i++
    if (i < str.length && (str[i] === '+' || str[i] === '-')) {
      i++
    }
    if (i >= str.length || !/\d/.test(str[i])) {
      const word = str.substring(0, i).match(/^[^\s#;,\]\}]*/)[0]
      throw new ParseError(lineNum, `invalid value ${word}`)
    }
    while (i < str.length && (/\d/.test(str[i]) || str[i] === '_')) {
      i++
    }
  }

  const numStr = str.substring(0, i).replace(/_/g, '')
  const num = Number(numStr)

  if (hasDecimal || hasExponent) {
    return { 
      value: { type: 'float', value: num },
      consumed: i
    }
  } else {
    return {
      value: { type: 'integer', value: num },
      consumed: i
    }
  }
}

function parseArray(str, lineNum) {
  if (str[0] !== '[') {
    throw new ParseError(lineNum, 'unterminated array')
  }

  const items = []
  let i = 1

  while (i < str.length) {
    // Skip whitespace and newlines
    while (i < str.length && /[\s]/.test(str[i])) {
      i++
    }

    if (i >= str.length) {
      throw new ParseError(lineNum, 'unterminated array')
    }

    if (str[i] === ']') {
      return { value: { type: 'array', value: items }, consumed: i + 1 }
    }

    // Skip comments
    if (str[i] === '#' || str[i] === ';') {
      while (i < str.length && str[i] !== '\n') {
        i++
      }
      if (i < str.length) {
        i++ // skip newline
      }
      continue
    }

    // Parse value
    const valueStr = str.substring(i)
    const result = parseValue(valueStr, lineNum)
    items.push(result.value)
    i += result.consumed

    // Skip whitespace
    while (i < str.length && /[\s]/.test(str[i])) {
      i++
    }

    if (i >= str.length) {
      throw new ParseError(lineNum, 'unterminated array')
    }

    if (str[i] === ',') {
      i++
      while (i < str.length && /[\s]/.test(str[i])) {
        i++
      }
      // Allow trailing comma and closing bracket
      if (i < str.length && str[i] === ']') {
        i++
        return { value: { type: 'array', value: items }, consumed: i }
      }
    } else if (str[i] === ']') {
      i++
      return { value: { type: 'array', value: items }, consumed: i }
    } else {
      throw new ParseError(lineNum, 'unterminated array')
    }
  }

  throw new ParseError(lineNum, 'unterminated array')
}

function parseInlineTable(str, lineNum) {
  if (str[0] !== '{') {
    throw new ParseError(lineNum, 'unterminated inline table')
  }

  const table = {}
  let i = 1

  while (i < str.length) {
    // Skip whitespace
    while (i < str.length && (str[i] === ' ' || str[i] === '\t')) {
      i++
    }

    if (i >= str.length) {
      throw new ParseError(lineNum, 'unterminated inline table')
    }

    if (str[i] === '}') {
      return { value: { type: 'table', value: table }, consumed: i + 1 }
    }

    // Parse key = value
    const remaining = str.substring(i)
    const eqPos = findUnquotedEquals(remaining, lineNum)
    if (eqPos === -1) {
      throw new ParseError(lineNum, 'expected = in an inline table')
    }

    const keyPart = remaining.substring(0, eqPos).trimEnd()
    const afterEq = remaining.substring(eqPos + 1).trimStart()

    const key = parseDottedName(keyPart, lineNum)
    const valueResult = parseValue(afterEq, lineNum)

    let finalTable = table
    for (let j = 0; j < key.length - 1; j++) {
      if (!finalTable[key[j]]) {
        finalTable[key[j]] = { type: 'table', value: {} }
      }
      finalTable = finalTable[key[j]].value
    }

    const lastKey = key[key.length - 1]
    if (finalTable.hasOwnProperty(lastKey)) {
      throw new ParseError(lineNum, `key ${key.join('.')} is defined twice`)
    }
    finalTable[lastKey] = valueResult.value

    i += eqPos + 1 + afterEq.length - afterEq.trimStart().length + valueResult.consumed

    // Skip whitespace
    while (i < str.length && (str[i] === ' ' || str[i] === '\t')) {
      i++
    }

    if (i >= str.length) {
      throw new ParseError(lineNum, 'unterminated inline table')
    }

    if (str[i] === ',') {
      i++
    } else if (str[i] === '}') {
      i++
      return { value: { type: 'table', value: table }, consumed: i }
    } else {
      throw new ParseError(lineNum, 'unterminated inline table')
    }
  }

  throw new ParseError(lineNum, 'unterminated inline table')
}

function findUnquotedEquals(str, lineNum) {
  let inString = false
  let stringChar = null

  for (let i = 0; i < str.length; i++) {
    const char = str[i]

    if (inString) {
      if (char === stringChar) {
        inString = false
      }
    } else {
      if (char === '"' || char === "'") {
        inString = true
        stringChar = char
      } else if (char === '=') {
        return i
      }
    }
  }

  return -1
}

function createTableHeader(doc, path, lineNum) {
  let current = doc

  for (let i = 0; i < path.length; i++) {
    const key = path[i]

    if (!current.hasOwnProperty(key)) {
      current[key] = { type: 'table', value: {}, _meta: { defined: false, implicit: i < path.length - 1 } }
    } else {
      const existing = current[key]
      if (existing.type !== 'table') {
        throw new ParseError(lineNum, `${path.slice(0, i + 1).join('.')} is not a table`)
      }
      if (i === path.length - 1) {
        if (!existing._meta.implicit) {
          throw new ParseError(lineNum, `table ${path.join('.')} is defined twice`)
        }
      }
    }

    if (i === path.length - 1) {
      current[key]._meta.defined = true
      current[key]._meta.implicit = false
    } else {
      current[key]._meta.implicit = true
    }

    current = current[key].value
  }

  return current
}

function createArrayOfTablesHeader(doc, path, lineNum) {
  let current = doc

  for (let i = 0; i < path.length - 1; i++) {
    const key = path[i]

    if (!current.hasOwnProperty(key)) {
      current[key] = { type: 'table', value: {} }
    } else {
      const existing = current[key]
      if (existing.type !== 'table') {
        throw new ParseError(lineNum, `${path.slice(0, i + 1).join('.')} is not a table`)
      }
    }

    current = current[key].value
  }

  const lastKey = path[path.length - 1]

  if (!current.hasOwnProperty(lastKey)) {
    current[lastKey] = { type: 'array', value: [] }
  } else {
    const existing = current[lastKey]
    if (existing.type !== 'array') {
      throw new ParseError(lineNum, `${path.join('.')} is not an array of tables`)
    }
  }

  const newTable = { type: 'table', value: {} }
  current[lastKey].value.push(newTable)

  return newTable.value
}

function assignValue(table, key, value, lineNum) {
  let current = table

  for (let i = 0; i < key.length - 1; i++) {
    const k = key[i]

    if (!current.hasOwnProperty(k)) {
      current[k] = { type: 'table', value: {} }
    } else {
      const existing = current[k]
      if (existing.type !== 'table' && existing.type !== 'array') {
        throw new ParseError(lineNum, `${key.slice(0, i + 1).join('.')} is not a table`)
      }
      if (existing.type === 'array') {
        current = existing.value[existing.value.length - 1].value
        continue
      }
    }

    current = current[k].value
  }

  const lastKey = key[key.length - 1]

  if (current.hasOwnProperty(lastKey)) {
    throw new ParseError(lineNum, `key ${key.join('.')} is defined twice`)
  }

  current[lastKey] = value
}

function toJsonString(obj) {
  // Treat root as a table value
  return toJson({ type: 'table', value: obj }, 0)
}

function toJson(val, indent) {
  const spaces = ' '.repeat(indent)
  const nextSpaces = ' '.repeat(indent + 2)

  if (val && val.type === 'table') {
    const keys = Object.keys(val.value).filter(k => !k.startsWith('_')).sort()
    if (keys.length === 0) {
      return '{}'
    }
    const lines = ['{']
    for (let i = 0; i < keys.length; i++) {
      const k = keys[i]
      const v = val.value[k]
      const formatted = toJson(v, indent + 2)
      const isLastKey = i === keys.length - 1
      lines.push(`${nextSpaces}"${k}": ${formatted}${isLastKey ? '' : ','}`)
    }
    lines.push(`${spaces}}`)
    return lines.join('\n')
  } else if (val && val.type === 'array') {
    if (val.value.length === 0) {
      return '[]'
    }
    const lines = ['[']
    for (let i = 0; i < val.value.length; i++) {
      const item = val.value[i]
      const formatted = toJson(item, indent + 2)
      const isLastItem = i === val.value.length - 1
      lines.push(`${nextSpaces}${formatted}${isLastItem ? '' : ','}`)
    }
    lines.push(`${spaces}]`)
    return lines.join('\n')
  } else if (val && val.type === 'string') {
    return JSON.stringify(val.value)
  } else if (val && val.type === 'boolean') {
    return val.value ? 'true' : 'false'
  } else if (val && val.type === 'integer') {
    return String(val.value)
  } else if (val && val.type === 'float') {
    return String(val.value)
  }
  return 'null'
}

function getKeys(obj, path = []) {
  const output = []
  const keys = Object.keys(obj).filter(k => !k.startsWith('_')).sort()

  for (const k of keys) {
    const v = obj[k]
    const newPath = [...path, k]
    const pathStr = newPath.join('.')

    if (v && v.type === 'table') {
      output.push(`${pathStr} table`)
      output.push(...getKeys(v.value, newPath))
    } else if (v && v.type === 'array') {
      output.push(`${pathStr} array`)
      for (let i = 0; i < v.value.length; i++) {
        const item = v.value[i]
        if (item && item.type === 'table') {
          output.push(...getKeys(item.value, [...newPath, `[${i}]`]))
        }
      }
    } else if (v && v.type) {
      output.push(`${pathStr} ${v.type}`)
    }
  }

  return output
}

