import { readFileSync, writeSync } from 'node:fs'
import { parse, ParseError } from './parser.js'
import { toJson, toKeys } from './format.js'

function write(fd, text) {
  const buffer = Buffer.from(text, 'utf8')
  let offset = 0
  while (offset < buffer.length) {
    offset += writeSync(fd, buffer, offset, buffer.length - offset)
  }
}

function die(message) {
  write(2, `${message}\n`)
  process.exit(2)
}

const argv = process.argv.slice(2)
if (argv.length !== 1 || (argv[0] !== 'json' && argv[0] !== 'keys')) {
  die('error: usage: cli.js json|keys')
}

let input = ''
try {
  input = readFileSync(0, 'utf8')
} catch {
  input = ''
}

let output
try {
  const document = parse(input)
  if (argv[0] === 'json') {
    output = `${toJson(document)}\n`
  } else {
    const lines = toKeys(document)
    output = lines.length === 0 ? '' : `${lines.join('\n')}\n`
  }
} catch (error) {
  if (error instanceof ParseError) die(error.message)
  throw error
}

write(1, output)
